/**
 * Static fallback for public Supabase reads.
 *
 * If the backend is restricted (HTTP 402/429, any 5xx such as the 503 the D1 backend returns when its daily quota is
 * exhausted, or a 400 carrying the D1 quota message), unreachable, or erroring, GET/HEAD requests to /rest/v1/<table>
 * for the snapshotted public tables are answered from /data/<table>.json (generated by scripts/snapshot-supabase.mjs).
 * - Ordinary application errors (400 for a bad filter / SQL error, 401/403/404 ...) are NEVER replaced by the snapshot.
 * - Writes are never faked and always go to the network.
 * - Requests carrying a signed-in user's JWT (the admin panel) are never answered from the snapshot, so the admin can
 *   neither read stale rows nor save them back over newer ones.
 * - While the snapshot is in use isStaticFallbackActive() is true; the IndexedDB cache refuses to store anything then.
 * Network is tried first so edits made in the admin panel are still live whenever the backend works.
 */
const TABLES = new Set(
  `travel_questions exam_questions applied_pharm_items articles drugs course_chapters icu_topics course_questions interview_questions rx_prescriptions icu_medications nicu_topics pharmacology_topics pediatric_topics quiz_questions er_medications fundamentals_topics first_aid_topics operating_room_topics terminology_topics peds_medications organ_dose_adjustments clinical_protocols obgyn_topics travel_review_sections dialysis_topics otc_conditions anatomy_topics er_reception_topics radiology_topics terminology_quiz_questions pediatric_quiz_questions pharmacy_facts pregnancy_lactation_safety iv_compatibility high_alert_ref lasa_pairs pharm_mnemonics drug_suffixes drug_classifications products exams ads exam_categories disease_images interview_categories tags site_settings drug_antidotes cardiac_med_groups courses media categories drug_interactions travel_categories pages affiliates redirects`.split(/\s+/),
);

type Row = Record<string, unknown>;
const cache = new Map<string, Promise<Row[]>>();
const DOWN_KEY = "nh_sb_down";
const DOWN_MS = 10 * 60 * 1000;

let servedAt = 0; // last time a response was answered from the snapshot (also covers browsers without sessionStorage)
const isDown = () => {
  try { return Date.now() - Number(sessionStorage.getItem(DOWN_KEY) || 0) < DOWN_MS; } catch { return false; }
};
const markDown = () => { servedAt = Date.now(); try { sessionStorage.setItem(DOWN_KEY, String(Date.now())); } catch { /* ignore */ } };

/** True while reads are (or were within the last 10 minutes) served from the static snapshot. */
export function isStaticFallbackActive(): boolean {
  return isDown() || Date.now() - servedAt < DOWN_MS;
}

/** Same signature as functions/_lib/sb.js isD1QuotaError: only the daily-quota message counts, other 400s are real errors. */
export function isD1QuotaMessage(msg: unknown): boolean {
  const m = String(msg ?? "");
  return /exceeded|free tier|daily (row|rows)? ?(read|write|written)? ?limit|quota/i.test(m) && /D1|free tier|rows? (read|written)|quota/i.test(m);
}

/** A request made with a signed-in user's access token (admin panel, own data): its token differs from the public apikey. */
function carriesUserToken(headers: Headers): boolean {
  const tok = (headers.get("authorization") || "").replace(/^Bearer\s+/i, "").trim();
  return !!tok && tok !== (headers.get("apikey") || "").trim() && tok.split(".").length === 3;
}

async function isOutage(res: Response): Promise<boolean> {
  if (res.status === 402 || res.status === 429 || res.status >= 500) return true;
  if (res.status !== 400) return false;
  try {
    const b = (await res.clone().json()) as { code?: string; message?: string };
    return (b?.code === "PGRST100" || b?.code === "PGRST000") && isD1QuotaMessage(b?.message);
  } catch { return false; }
}

function load(table: string): Promise<Row[]> {
  let p = cache.get(table);
  if (!p) {
    p = fetch(`/data/${table}.json`).then((r) => (r.ok ? (r.json() as Promise<Row[]>) : Promise.reject(new Error("no snapshot"))));
    p.catch(() => cache.delete(table));
    cache.set(table, p);
  }
  return p;
}

const parseVal = (v: string): unknown => (v === "null" ? null : v === "true" ? true : v === "false" ? false : v);
const cmp = (a: unknown, b: unknown) => {
  const na = Number(a), nb = Number(b);
  if (a !== "" && b !== "" && !Number.isNaN(na) && !Number.isNaN(nb) && typeof a !== "boolean") return na - nb;
  return String(a ?? "").localeCompare(String(b ?? ""));
};
function matchFilter(row: Row, col: string, expr: string): boolean {
  const dot = expr.indexOf(".");
  if (dot < 0) return true;
  const neg = expr.startsWith("not.");
  const e = neg ? expr.slice(4) : expr;
  const d = e.indexOf(".");
  const op = e.slice(0, d), raw = e.slice(d + 1);
  const val = row[col];
  let ok = true;
  switch (op) {
    case "eq": ok = String(val) === raw; break;
    case "neq": ok = String(val) !== raw; break;
    case "gt": ok = cmp(val, raw) > 0; break;
    case "gte": ok = cmp(val, raw) >= 0; break;
    case "lt": ok = cmp(val, raw) < 0; break;
    case "lte": ok = cmp(val, raw) <= 0; break;
    case "is": ok = parseVal(raw) === (val ?? null) || (raw === "null" && val == null); break;
    case "in": ok = raw.replace(/^\(|\)$/g, "").split(",").map((x) => x.replace(/^"|"$/g, "")).includes(String(val)); break;
    case "like": case "ilike": {
      const re = new RegExp("^" + raw.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*|%/g, ".*") + "$", op === "ilike" ? "i" : "");
      ok = re.test(String(val ?? "")); break;
    }
    default: ok = true; // unsupported operator → keep the row (superset is safer than an empty list)
  }
  return neg ? !ok : ok;
}

async function answer(table: string, url: URL, method: string, headers: Headers): Promise<Response> {
  let rows = await load(table);
  const q = url.searchParams;
  for (const [k, v] of q.entries()) {
    if (["select", "order", "limit", "offset", "columns", "on_conflict"].includes(k) || k === "or" || k === "and") continue;
    rows = rows.filter((r) => matchFilter(r, k, v));
  }
  const order = q.get("order");
  if (order) {
    const keys = order.split(",").map((s) => { const [c, dir] = s.split("."); return { c, desc: dir === "desc" }; });
    rows = [...rows].sort((a, b) => { for (const { c, desc } of keys) { const x = cmp(a[c], b[c]); if (x) return desc ? -x : x; } return 0; });
  }
  const total = rows.length;
  const off = Number(q.get("offset") || 0);
  const lim = q.get("limit") ? Number(q.get("limit")) : undefined;
  const range = headers.get("range");
  let from = off, to = lim != null ? off + lim - 1 : total - 1;
  if (range && /^\d+-\d+$/.test(range)) { const [a, b] = range.split("-").map(Number); from = a; to = b; }
  rows = rows.slice(from, to + 1);
  const cr = `${rows.length ? from : "*"}${rows.length ? `-${from + rows.length - 1}` : ""}/${total}`.replace("*/", "*/");
  const h = { "content-type": "application/json", "content-range": rows.length ? `${from}-${from + rows.length - 1}/${total}` : `*/${total}`, "x-static-fallback": "1" };
  void cr;
  if (method === "HEAD") return new Response(null, { status: 200, headers: h });
  if ((headers.get("accept") || "").includes("vnd.pgrst.object")) {
    if (rows.length !== 1) return new Response(JSON.stringify({ code: "PGRST116", message: "JSON object requested, multiple (or no) rows returned" }), { status: 406, headers: h });
    return new Response(JSON.stringify(rows[0]), { status: 200, headers: h });
  }
  return new Response(JSON.stringify(rows), { status: 200, headers: h });
}

/** Public storage files that were copied to Cloudflare (public/media, see scripts/snapshot-storage.mjs). */
let localFiles: Promise<Set<string>> | null = null;
const loadLocalFiles = () => (localFiles ??= fetch("/media/manifest.json").then((r) => (r.ok ? r.json() : [])).then((a: string[]) => new Set(a)).catch(() => new Set<string>()));

/** Old Supabase project that the stored URLs may still point at (public info). */
const LEGACY_HOSTS = ["https://vpgzbjbcbrbexpzoxrup.supabase.co"];

async function rewriteMedia(res: Response, baseUrl: string): Promise<Response> {
  if (!(res.headers.get("content-type") || "").includes("json")) return res;
  const text = await res.clone().text();
  const hosts = [baseUrl.replace(/\/$/, ""), ...LEGACY_HOSTS];
  const markers = hosts.map((h) => `${h}/storage/v1/object/public/media/`);
  if (!markers.some((m) => text.includes(m))) return res;
  const files = await loadLocalFiles();
  let out = text;
  for (const marker of markers) {
    const esc = marker.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    out = out.replace(new RegExp(esc + "([^\"\\\\\\s)<>?]+)", "g"), (m, path: string) => {
      let dec = path; try { dec = decodeURIComponent(path); } catch { /* keep */ }
      return files.has(`media/${dec}`) ? `/media/media/${path}` : m;
    });
  }
  if (out === text) return res;
  return new Response(out, { status: res.status, statusText: res.statusText, headers: res.headers });
}

export function withStaticFallback(baseUrl: string): typeof fetch {
  const restBase = `${baseUrl.replace(/\/$/, "")}/rest/v1/`;
  return async (input, init) => {
    const req = input instanceof Request ? input : null;
    const urlStr = typeof input === "string" ? input : input instanceof URL ? input.href : (req as Request).url;
    const method = (init?.method || req?.method || "GET").toUpperCase();
    if ((method !== "GET" && method !== "HEAD") || !urlStr.startsWith(restBase)) return fetch(input, init);
    const url = new URL(urlStr);
    const table = url.pathname.split("/rest/v1/")[1];
    if (!TABLES.has(table)) return fetch(input, init);
    const headers = new Headers(init?.headers || req?.headers);
    if (carriesUserToken(headers)) return fetch(input, init); // admin / signed-in reads are always live
    if (isDown()) {
      try { return await rewriteMedia(await answer(table, url, method, headers), baseUrl); } catch { /* fall through to network */ }
    }
    try {
      const res = await fetch(input, init);
      if (await isOutage(res)) {
        markDown();
        try { return await rewriteMedia(await answer(table, url, method, headers), baseUrl); } catch { return res; }
      }
      return method === "GET" ? await rewriteMedia(res, baseUrl) : res;
    } catch (e) {
      markDown();
      try { return await rewriteMedia(await answer(table, url, method, headers), baseUrl); } catch { throw e; }
    }
  };
}
